#!/usr/bin/env bash
# Bundle item 217b commerce_smegov19_notice (thread "Site: Add Commerce and Industry committee", 25 Nov 2569, routine check 05:49 UTC)
# Commerce 2569, routine content only (no design change). Senate file used is Rpublic=1.
#   smegov sub 19 (Tue 1 Dec 2569): NEW upcoming card from notice ref 11254314 (สว (กมธ ๑) ๐๐๐๙/ว๑๐๕๘, 24 Nov):
#   10.00, ห้องประชุมกรรมาธิการ CB 311 (สว.) ชั้น 3; agenda: considering the draft study report on promoting the
#   Kanchanaburi Special Economic Development Zone. smegov 18 (24 Nov) no longer "upcoming".
# Surgical like items 152/176: DATA, SUBS, SHARE_V, TL, EZ.cal, UPDATED lines in sub-smegov.html / index.html (SUBS),
# sub-smegov.json, share card (s/, img/s/), calendar file cal-sub/smegov/19.ics, i18n-en.json (5 missing keys only),
# then meeting_pages.py rebuilds m/*.html (m/smegov-19.html is new). Independent of item 217; works in either order.
# Self-contained (payload embedded, md5-checked). Idempotent; no git, no network. Needs $HUB ($BUILD optional).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
T=217b_commerce_smegov19_notice
M="$HUB/commerce/2569"
for f in index.html sub-smegov.html sub-smegov.json i18n-en.json; do
  test -f "$M/$f" || { echo "$T: $M/$f missing" >&2; exit 1; }; done
PAY="$(mktemp -d)"; trap 'rm -rf "$PAY"' EXIT
base64 -d > "$PAY/p.tgz" <<'B64'
