tar -xzf "$PAY/p.tgz" -C "$PAY"; rm -f "$PAY/p.tgz"
test "$(md5sum < "$PAY/payload_217b.json" | cut -c1-32)" = ec447ee3175523af1bf7d6016a9f76ce || { echo "$T: embedded payload damaged" >&2; exit 1; }
test "$(md5sum < "$PAY/apply.py" | cut -c1-32)" = f7d6d611b4c23a0ae08fa4b83ebd7a7d || { echo "$T: embedded apply.py damaged" >&2; exit 1; }
test "$(md5sum < "$PAY/meeting_pages.py" | cut -c1-32)" = 6a115e8dce53e6b83bd9db5a477f1f55 || { echo "$T: embedded meeting_pages.py damaged" >&2; exit 1; }
python3 "$PAY/apply.py" "$M" "$PAY/payload_217b.json"
MP="$BUILD/meeting_pages.py"; test -s "$MP" || MP="$PAY/meeting_pages.py"
python3 "$MP" "$M" >/dev/null
python3 - "$M" <<'PY'
import json, os, sys
M = sys.argv[1]; dec = json.JSONDecoder()
def val(p, c):
    for l in open(p, encoding="utf-8").read().split("\n"):
        if l.startswith(c): return dec.raw_decode(l[len(c):])[0]
    raise SystemExit("217b: " + c + " missing in " + p)
def refs(e): return [d["url"].rsplit("ref=", 1)[-1] for d in e.get("docs", [])]
srcs = [{m["n"]: m for m in val(f"{M}/sub-smegov.html", "const DATA=")},
        {m["n"]: m for m in json.load(open(f"{M}/sub-smegov.json", encoding="utf-8"))}]
for s in srcs:
    e = s[19]
    assert e["date"] == "2026-12-01" and e["time"] == "10.00" and "CB 311" in e["room"] and e.get("upcoming"), "217b: smegov 19 card"
    assert "11254314" in refs(e) and "กาญจนบุรี" in e["headline"], "217b: smegov 19 notice/headline"
    assert not s[18].get("upcoming") and "11225978" in refs(s[18]), "217b: smegov 18"
    assert [v["ck"] for v in s[18]["media"]["videos"]] == ["smegov-18p"], "217b: smegov 18 pre video kept"
g = {m["n"]: m for m in [x for x in val(f"{M}/index.html", "const SUBS=") if x["key"] == "smegov"][0]["meetings"]}
assert "11254314" in refs(g[19]) and not g[18].get("upcoming"), "217b: SUBS"
assert any(r[-1] == 19 for r in val(f"{M}/sub-smegov.html", "const TL=")), "217b: TL"
assert "19" in val(f"{M}/sub-smegov.html", "const EZ=").get("cal", {}), "217b: EZ.cal"
for f in ("m/smegov-19.html", "s/smegov-19.html", "cal-sub/smegov/19.ics", "img/s/qr-smegov-19.svg"):
    assert os.path.getsize(f"{M}/{f}") > 200, "217b: " + f
assert "ref=11254314" in open(f"{M}/m/smegov-19.html", encoding="utf-8").read(), "217b: m/smegov-19.html notice"
en = json.load(open(f"{M}/i18n-en.json", encoding="utf-8"))
assert en.get("พิจารณาร่างรายงานการศึกษาแนวทางส่งเสริมเขตพัฒนาเศรษฐกิจพิเศษจังหวัดกาญจนบุรี"), "217b: i18n"
print("217b_commerce_smegov19_notice OK")
PY
